// Node: Build Sync Window   ([SPL] Simpro -> HubSpot Sites Sync)
// Sync window + config for this poller. Single source of truth: edit values HERE only.
// The watermark lives in THIS workflow's own static data, so the five sync workflows never share a window.
const CONFIG = {
  recordType: 'site', // company | contact | site | quote | job
  label: 'Sites',
  // --- Simpro ---
  simproBaseUrl: 'https://spl.simprosuite.com/api/v1.0',
  listPath: 'companies/0/sites/', // changed-since list (If-Modified-Since). Quotes and Jobs use Simpro company ID 4 (confirmed with SPL).
  detailPath: 'companies/0/sites/', // + record ID = the full record
  // --- HubSpot ---
  hubspotApiBase: 'https://api.hubapi.com',
  objectPath: 'crm/objects/2026-09/0-420',
  assocObject: '0-420', // object type name used by the associations API
  idProperty: 'simpro_site_id', // unique HubSpot property that holds the Simpro ID
  needsReadBack: true, // read the HubSpot IDs back after the write
  hubspotBatchSize: 100, // HubSpot batch limit
  // --- Test-record rule (do not loosen without asking SPL) ---
  testRecords: { namePrefix: 'HS TEST - ', contactEmailDomains: ['aniccadigital.io', 'spl.com', 'spl.com.au'] },
  // --- Window ---
  overlapMinutes: 2, // re-read this far back from the last window end (clock skew / late commits). Writes are idempotent.
  initialLookbackMinutes: 35, // used when there is no saved watermark (first run, or any manual test run)
  windowStartOverride: '', // optional ISO date-time e.g. '2026-11-20T00:00:00Z' - forces the window start (backfill / recovery). Clear afterwards.
};

const state = $getWorkflowStaticData('global'); // only persists on production (trigger) runs, not manual test runs
const now = new Date();
let from;
let fromSource;

if (CONFIG.windowStartOverride) {
  from = new Date(CONFIG.windowStartOverride);
  if (isNaN(from.getTime())) {
    throw new Error('windowStartOverride is not a valid ISO date-time: ' + CONFIG.windowStartOverride);
  }
  fromSource = 'override';
} else if (state.lastWindowEnd) {
  from = new Date(new Date(state.lastWindowEnd).getTime() - CONFIG.overlapMinutes * 60000);
  fromSource = 'watermark';
} else {
  from = new Date(now.getTime() - CONFIG.initialLookbackMinutes * 60000);
  fromSource = 'initial lookback';
}
if (from.getTime() >= now.getTime()) {
  throw new Error('Sync window starts in the future (' + from.toISOString() + '). Check windowStartOverride and the saved watermark.');
}

return [{ json: {
  ...CONFIG,
  listUrl: CONFIG.simproBaseUrl + '/' + CONFIG.listPath,
  detailUrlPrefix: CONFIG.simproBaseUrl + '/' + CONFIG.detailPath,
  objectUrl: CONFIG.hubspotApiBase + '/' + CONFIG.objectPath,
  windowFrom: from.toISOString(),
  windowTo: now.toISOString(),
  ifModifiedSince: from.toUTCString(), // Simpro If-Modified-Since needs an HTTP-date in GMT
  fromSource,
} }];

// Node: Build Record List   (all five sync workflows)
// Turns the paged "changed since" list from Simpro into ONE item per changed record ID (deduplicated).
// FAN-OUT: everything after this runs once per item until Select Test Records collapses it again.
const cfg = $('Build Sync Window').first().json;
const pages = $('Fetch Changed Records').all().map(i => i.json); // one item per page (fullResponse)

const ids = [];
const seen = new Set();
let rows = 0;
let reportedTotal = null;

for (const page of pages) {
  if (page.statusCode === 304) continue; // Simpro: nothing modified since the window start
  if (page.statusCode !== 200) {
    throw new Error('Fetch Changed Records: Simpro returned HTTP ' + page.statusCode + ' - ' + JSON.stringify(page.body).slice(0, 300));
  }
  if (!Array.isArray(page.body)) {
    throw new Error('Fetch Changed Records: expected a JSON array from Simpro, got ' + typeof page.body);
  }
  if (reportedTotal === null && page.headers && page.headers['result-total'] !== undefined) {
    reportedTotal = Number(page.headers['result-total']);
  }
  for (const row of page.body) {
    if (row === null || typeof row !== 'object' || row.ID === undefined || row.ID === null) {
      throw new Error('Fetch Changed Records: a returned record has no ID - check the columns=ID query parameter.');
    }
    rows++;
    const id = String(row.ID);
    if (seen.has(id)) continue;
    seen.add(id);
    ids.push(id);
  }
}

// The pagination cap stops silently - fail loudly instead of syncing a partial window.
if (reportedTotal !== null && rows < reportedTotal) {
  throw new Error('Fetch Changed Records: read ' + rows + ' of ' + reportedTotal + ' changed ' + cfg.label
    + ' (page cap of 40 x 100 reached). Shorten the window (windowStartOverride in Build Sync Window) or raise Max Pages on that node.');
}

if (ids.length === 0) {
  return [{ json: { hasRecords: false, count: 0 } }];
}
return ids.map(id => ({ json: { hasRecords: true, id } }));

// Node: Select Test Records   (all five sync workflows)
// Collapses the per-record Simpro detail results into ONE item and applies the test-record rule
// BEFORE anything is written to HubSpot. Same rule as [SPL] Check Simpro Test Record:
//   Contacts: email domain is one of testRecords.contactEmailDomains (exact match, not case-sensitive).
//   Everything else: name starts with testRecords.namePrefix (not case-sensitive).
// Do not loosen this without asking SPL.
const cfg = $('Build Sync Window').first().json;
const ids = $('Build Record List').all().map(i => String(i.json.id));
const prefix = String(cfg.testRecords.namePrefix).toLowerCase();
const domains = cfg.testRecords.contactEmailDomains.map(d => String(d).trim().toLowerCase()).filter(Boolean);

const isTestRecord = (rec) => {
  if (cfg.recordType === 'contact') {
    const email = String(rec.Email ?? '').trim().toLowerCase();
    const domain = email.includes('@') ? email.split('@').pop() : '';
    return domains.includes(domain);
  }
  const name = String(rec.Name ?? rec.CompanyName ?? [rec.GivenName, rec.FamilyName].filter(Boolean).join(' ')).trim();
  return name.toLowerCase().startsWith(prefix);
};

const records = [];
let skippedNonTest = 0;
const skippedGone = [];
const failures = [];

$input.all().forEach((item, k) => {
  // With "continue on error" a failed fetch comes back as an item carrying `error`, paired to its input item.
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
  const simproId = ids[idx];
  const j = item.json ?? {};
  if (j.error !== undefined && (j.ID === undefined || j.ID === null)) {
    const msg = typeof j.error === 'string' ? j.error : JSON.stringify(j.error);
    if (/\b404\b|could not be found|not found/i.test(msg)) skippedGone.push(simproId); // deleted since it was listed
    else failures.push({ type: cfg.recordType, id: simproId, error: msg.slice(0, 300) });
    return;
  }
  if (j.ID === undefined || j.ID === null) {
    failures.push({ type: cfg.recordType, id: simproId, error: 'Simpro returned a record with no ID' });
    return;
  }
  if (isTestRecord(j)) records.push(j);
  else skippedNonTest++;
});

return [{ json: { fetched: ids.length, records, skippedNonTest, skippedGone, failures } }];

// Node: Build Upsert Batches   ([SPL] Simpro -> HubSpot Sites Sync)
// Simpro site -> HubSpot Site (0-420), keyed on the unique property simpro_site_id.
// Same property mapping as [SPL] Upsert Site in HubSpot. One batch call per 100 sites.
const cfg = $('Build Sync Window').first().json;
const { records } = $('Select Test Records').first().json;
const blank = (v) => v === null || v === undefined || v === '' || v === 'null';
const keep = (o) => Object.fromEntries(Object.entries(o).filter(([, v]) => !blank(v)).map(([k, v]) => [k, String(v)]));
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));

const inputs = records.map((site) => ({
  idProperty: cfg.idProperty,
  id: String(site.ID), // the unique ID property is set from this on create
  properties: keep({
    hs_name: site.Name,
    hs_address_1: site.Address?.Address,
    hs_city: site.Address?.City,
    hs_state_province: site.Address?.State,
    hs_zip: site.Address?.PostalCode,
    country: site.Address?.Country,
    zone: site.Zone?.ID,
    billing_address: site.BillingAddress?.Address,
    billing_city: site.BillingAddress?.City,
    billing_state: site.BillingAddress?.State,
    billing_postal_code: site.BillingAddress?.PostalCode,
  }),
}));

return chunk(inputs, cfg.hubspotBatchSize).map((part, n) => ({
  json: { url: cfg.objectUrl + '/batch/upsert', body: { inputs: part }, meta: { kind: 'upsert', batch: n + 1, count: part.length } },
}));

// Node: Check Upsert Results   (all five sync workflows)
// HubSpot batch endpoints answer 200/207 even when single records were rejected, so inspect every
// response, and guard the count: if HubSpot returned a different number of results than we sent,
// stop (the window is NOT advanced, the next run re-reads it; upserts are idempotent).
const cfg = $('Build Sync Window').first().json;
const { records } = $('Select Test Records').first().json;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));

const errors = [];
let written = 0;
for (const item of $input.all()) {
  const b = item.json ?? {};
  const errs = Array.isArray(b.errors) ? b.errors : [];
  if (errs.length || Number(b.numErrors) > 0) {
    errors.push(...errs.map(e => (e && (e.message || e.category)) || JSON.stringify(e)));
    if (!errs.length) errors.push('numErrors=' + b.numErrors);
  }
  written += Array.isArray(b.results) ? b.results.length : 0;
}
if (errors.length) {
  throw new Error('HubSpot rejected part of the ' + cfg.label + ' batch. The window is NOT advanced. First errors: ' + errors.slice(0, 5).join(' | '));
}
if (written !== records.length) {
  throw new Error('HubSpot returned ' + written + ' result(s) for ' + records.length + ' ' + cfg.label
    + ' sent - NOT advancing the window. Re-run; if it repeats, check for duplicate Simpro IDs/emails in one batch.');
}

// ONE state item. When IDs are needed afterwards (associations / line items) it carries the read-back
// requests: the HubSpot ID of every record, read by the unique Simpro ID property. Split Read-Back Requests
// turns them into one item per batch call.
const requests = cfg.needsReadBack
  ? chunk(records.map(r => ({ id: String(r.ID) })), cfg.hubspotBatchSize).map((part, n) => ({
      url: cfg.objectUrl + '/batch/read',
      body: { idProperty: cfg.idProperty, properties: [cfg.idProperty], inputs: part },
      meta: { kind: 'readBack', batch: n + 1, count: part.length },
    }))
  : [];
return [{ json: { written, requests } }];

// Node: Split ... Requests   (all workflows that make batch calls)
// Turns the ONE state item from the previous Code node into one item per HubSpot/Simpro call.
// No requests = a single { skip: true } item, which the next "Any ...?" check routes around the call.
const requests = $input.first().json.requests ?? [];
if (requests.length === 0) return [{ json: { skip: true } }];
return requests.map(r => ({ json: r }));

// Node: Build Association Reads   ([SPL] Simpro -> HubSpot Sites Sync)
// 1) Turns the read-back answers into Simpro ID -> HubSpot ID for the records just written.
// 2) Works out which related Simpro records each record should link to (LINKS below).
// 3) Builds ONE set of read requests: the HubSpot IDs of the related records (by their unique Simpro ID
//    property) and, for reconcile links, the links each record has in HubSpot right now.
const cfg = $('Build Sync Window').first().json;
const { records } = $('Select Test Records').first().json;
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));

// Link ownership (agreed with SPL): the CHILD record manages its own links, so two workflows never fight
// over the same link. reconcile = keep matches, remove stale, add missing. addOnly = add missing, never remove.
const LINKS = [
  // Site owns Site <-> Company (reconcile) ...
  { key: 'company', toType: 'company', mode: 'reconcile', desired: (r) => (r.Customers ?? []).map(c => c.ID) },
  // ... and makes sure its primary contact is linked (add-only: other contacts' links belong to the Contact workflow).
  { key: 'primaryContact', toType: 'contact', mode: 'addOnly', desired: (r) => [r.PrimaryContact?.Contact?.ID] },
];

const OBJECTS = {
  company: { object: 'companies', path: 'crm/objects/2026-09/companies', idProperty: 'simpro_customer_id' },
  contact: { object: 'contacts', path: 'crm/objects/2026-09/contacts', idProperty: 'simpro_contact_id' },
  site: { object: '0-420', path: 'crm/objects/2026-09/0-420', idProperty: 'simpro_site_id' },
};

const hsIdBySimproId = {};
for (const item of $input.all()) {
  const r = item.json ?? {};
  if (r.statusCode !== 200 && r.statusCode !== 207) {
    throw new Error('Read Back HubSpot IDs failed (HTTP ' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300));
  }
  for (const x of ((r.body && r.body.results) || [])) {
    const sid = x.properties ? x.properties[cfg.idProperty] : undefined;
    if (sid !== undefined && sid !== null) hsIdBySimproId[String(sid)] = String(x.id);
  }
}
const idMap = {};
const missing = [];
for (const r of records) {
  const sid = String(r.ID);
  if (hsIdBySimproId[sid] === undefined) missing.push(sid); else idMap[sid] = hsIdBySimproId[sid];
}
if (missing.length) {
  throw new Error('HubSpot has no ' + cfg.label + ' record for Simpro ID ' + missing.slice(0, 10).join(', ')
    + ' straight after the write - NOT advancing the window. Re-run.');
}

const desired = {}; // linkKey -> simproId -> [related simpro ids]
const primary = {}; // linkKey -> simproId -> primary related simpro id (links with a label only)
const needed = {};  // toType -> Set(related simpro ids)
for (const l of LINKS) {
  desired[l.key] = {};
  primary[l.key] = {};
  for (const r of records) {
    const ids = [...new Set((l.desired(r) ?? [])
      .filter(v => v !== undefined && v !== null && v !== '').map(String))];
    desired[l.key][String(r.ID)] = ids;
    if (l.primary) {
      const p = l.primary(r);
      primary[l.key][String(r.ID)] = (p === undefined || p === null || p === '') ? null : String(p);
    }
    for (const id of ids) { (needed[l.toType] = needed[l.toType] ?? new Set()).add(id); }
  }
}
const plan = {
  idMap,
  desired,
  primary,
  links: LINKS.map(l => ({ key: l.key, toType: l.toType, mode: l.mode, label: l.label ?? null, fromObject: cfg.assocObject, toObject: OBJECTS[l.toType].object })),
};

const requests = [];
for (const [toType, set] of Object.entries(needed)) {
  const o = OBJECTS[toType];
  chunk([...set], cfg.hubspotBatchSize).forEach((part, n) => requests.push({
    url: cfg.hubspotApiBase + '/' + o.path + '/batch/read',
    body: { idProperty: o.idProperty, properties: [o.idProperty], inputs: part.map(id => ({ id })) },
    meta: { kind: 'lookup', toType, idProperty: o.idProperty, batch: n + 1 },
  }));
}
const fromIds = Object.values(idMap);
for (const l of plan.links) {
  if (l.mode !== 'reconcile') continue; // addOnly links never need the current links
  chunk(fromIds, cfg.hubspotBatchSize).forEach((part, n) => requests.push({
    url: cfg.hubspotApiBase + '/crm/v4/associations/' + l.fromObject + '/' + l.toObject + '/batch/read',
    body: { inputs: part.map(id => ({ id })) },
    meta: { kind: 'current', linkKey: l.key, batch: n + 1 },
  }));
}
if (requests.length === 0) {
  throw new Error('Build Association Reads produced no requests - check LINKS in this node.');
}
// ONE state item; Split Association Reads turns the requests into one item per call.
return [{ json: { plan, requests } }];

// Node: Split ... Requests   (all workflows that make batch calls)
// Turns the ONE state item from the previous Code node into one item per HubSpot/Simpro call.
// No requests = a single { skip: true } item, which the next "Any ...?" check routes around the call.
const requests = $input.first().json.requests ?? [];
if (requests.length === 0) return [{ json: { skip: true } }];
return requests.map(r => ({ json: r }));

// Node: Plan Association Changes   (site, contact, quote and job workflows)
// Reads the answers to Build Association Reads, then diffs what HubSpot links now with what Simpro says:
//   reconcile links: keep matches, remove stale links, add missing ones.
//   addOnly links:   add missing ones, never remove (a link owned by another workflow, or ambiguous).
//   links with a `label` (Quote/Job -> Contact): the PRIMARY contact must carry the label (HubSpot user-defined
//   association, e.g. Decision Maker); the other (additional) contacts are linked with NO label. A label limit of
//   1-to-many means only one contact per deal can hold it, so a contact that holds the label but is no longer
//   the primary is unlinked first (archive) and re-linked without a label if it is still wanted.
// A related record that is not in HubSpot yet is SKIPPED and reported in the run summary (warnings).
// Output: ONE item { summary, requests } (requests may be empty = already in sync).
const cfg = $('Build Sync Window').first().json;
const plan = $('Build Association Reads').first().json.plan;
const built = $('Split Association Reads').all(); // the requests, in the order they were sent
const chunk = (arr, n) => Array.from({ length: Math.ceil(arr.length / n) }, (_, i) => arr.slice(i * n, i * n + n));
const okStatus = (s) => s === 200 || s === 207;

const lookup = {};  // toType -> { simproId: hubspotId }
const current = {}; // linkKey -> { fromHubspotId: Set(toHubspotId) }
const haveTypes = {}; // linkKey -> { fromHubspotId: { toHubspotId: Set(association type IDs) } }
plan.links.forEach(l => { current[l.key] = {}; haveTypes[l.key] = {}; });

$input.all().forEach((item, k) => {
  const idx = (item.pairedItem && item.pairedItem.item !== undefined) ? item.pairedItem.item : k;
  const meta = built[idx].json.meta;
  const r = item.json ?? {};
  if (r.statusCode === 404) return; // nothing found / no associations yet
  if (!okStatus(r.statusCode)) {
    throw new Error('HubSpot ' + meta.kind + ' read failed (HTTP ' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300));
  }
  const results = (r.body && Array.isArray(r.body.results)) ? r.body.results : [];
  if (meta.kind === 'lookup') {
    lookup[meta.toType] = lookup[meta.toType] ?? {};
    for (const x of results) {
      const simproId = x.properties ? x.properties[meta.idProperty] : undefined;
      if (simproId !== undefined && simproId !== null) lookup[meta.toType][String(simproId)] = String(x.id);
    }
  } else {
    for (const row of results) {
      const from = String(row.from && row.from.id);
      current[meta.linkKey][from] = new Set((row.to ?? []).map(t => String(t.toObjectId)));
      haveTypes[meta.linkKey][from] = {};
      for (const t of (row.to ?? [])) {
        haveTypes[meta.linkKey][from][String(t.toObjectId)] = new Set((t.associationTypes ?? []).map(a => Number(a.typeId)));
      }
    }
  }
});

const warnings = [];
const requests = [];
let removed = 0;
let added = 0;

for (const l of plan.links) {
  const archiveInputs = [];
  const addInputs = [];
  const labelInputs = [];
  const labelType = l.label ? l.label.types[0].associationTypeId : null;
  for (const [simproId, fromHs] of Object.entries(plan.idMap)) {
    const wantedHs = new Set();
    for (const relatedSimproId of (plan.desired[l.key][simproId] ?? [])) {
      const hs = lookup[l.toType] ? lookup[l.toType][relatedSimproId] : undefined;
      if (hs) wantedHs.add(hs);
      else warnings.push({ link: l.key, simproId, relatedSimproId, reason: 'related ' + l.toType + ' not in HubSpot yet - link skipped' });
    }
    const primarySimproId = l.label ? (plan.primary[l.key][simproId] ?? null) : null;
    const primaryHs = primarySimproId && lookup[l.toType] ? (lookup[l.toType][primarySimproId] ?? null) : null;
    const have = l.mode === 'reconcile' ? (current[l.key][fromHs] ?? new Set()) : new Set();
    const types = (haveTypes[l.key] && haveTypes[l.key][fromHs]) || {};

    const rem = [...have].filter(id => !wantedHs.has(id));
    // holds the label but is not (or no longer) the primary: unlink, then re-link without a label below
    const dropLabel = l.label ? [...have].filter(id => wantedHs.has(id) && id !== primaryHs && types[id] && types[id].has(labelType)) : [];
    const toArchive = [...rem, ...dropLabel];
    if (toArchive.length) { archiveInputs.push({ from: { id: fromHs }, to: toArchive.map(id => ({ id })) }); removed += rem.length; }

    for (const id of wantedHs) {
      if (l.label && id === primaryHs) continue; // handled below with the label
      if (!have.has(id) || dropLabel.includes(id)) { addInputs.push({ from: { id: fromHs }, to: { id } }); added++; }
    }
    if (l.label && primaryHs && !(have.has(primaryHs) && types[primaryHs] && types[primaryHs].has(labelType))) {
      labelInputs.push({ from: { id: fromHs }, to: { id: primaryHs }, types: l.label.types });
      added++;
    }
  }
  const base = cfg.hubspotApiBase + '/crm/v4/associations/' + l.fromObject + '/' + l.toObject;
  // Order matters (requests run in order): archive first, then unlabelled adds, then the labelled primary.
  chunk(archiveInputs, cfg.hubspotBatchSize).forEach((part, n) => requests.push({
    url: base + '/batch/archive', body: { inputs: part }, meta: { kind: 'archive', link: l.key, batch: n + 1 } }));
  chunk(addInputs, cfg.hubspotBatchSize).forEach((part, n) => requests.push({
    url: base + '/batch/associate/default', body: { inputs: part }, meta: { kind: 'associate', link: l.key, batch: n + 1 } }));
  chunk(labelInputs, cfg.hubspotBatchSize).forEach((part, n) => requests.push({
    url: base + '/batch/create', body: { inputs: part }, meta: { kind: 'associateLabelled', link: l.key, batch: n + 1 } }));
}

const summary = { removed, added, warningCount: warnings.length, warnings: warnings.slice(0, 50) };
// ONE state item; Split Association Requests turns the requests into one item per batch call.
return [{ json: { summary, requests } }];

// Node: Split ... Requests   (all workflows that make batch calls)
// Turns the ONE state item from the previous Code node into one item per HubSpot/Simpro call.
// No requests = a single { skip: true } item, which the next "Any ...?" check routes around the call.
const requests = $input.first().json.requests ?? [];
if (requests.length === 0) return [{ json: { skip: true } }];
return requests.map(r => ({ json: r }));

// Node: Check Association Results   (site, contact, quote and job workflows)
// Reached either after Apply Association Changes or straight from "no changes" (skip item).
// Batch endpoints answer 2xx even when single links were rejected, so inspect the bodies.
let summary = { removed: 0, added: 0, warningCount: 0, warnings: [] };
try { summary = $('Plan Association Changes').first().json.summary ?? summary; } catch (e) { /* not executed */ }

const errors = [];
for (const item of $input.all()) {
  const b = item.json ?? {};
  if (b.skip) continue;
  const errs = Array.isArray(b.errors) ? b.errors : [];
  if (errs.length || Number(b.numErrors) > 0) {
    errors.push(...errs.map(e => (e && (e.message || e.category)) || JSON.stringify(e)));
    if (!errs.length) errors.push('numErrors=' + b.numErrors);
  }
}
if (errors.length) {
  throw new Error('HubSpot rejected part of the association changes. The window is NOT advanced. First errors: ' + errors.slice(0, 5).join(' | '));
}
return [{ json: { associations: summary } }];

// Node: Finish Run   (all five sync workflows)
// Runs ONCE per poll: when everything is done, or straight away when there was nothing to sync.
// Fails the run (-> error workflow) if any record failed; only advances the watermark on full success.
const cfg = $('Build Sync Window').first().json;
const get = (name) => { try { return $(name).first().json; } catch (e) { return null; } }; // null when that branch did not run

const changed = $('Build Record List').all().filter(i => i.json.hasRecords === true).length;
const sel = get('Select Test Records');
const upsert = get('Check Upsert Results');
const assoc = get('Check Association Results');
const li = get('Check Line Item Results');

const failures = [...((sel && sel.failures) || []), ...((li && li.failures) || [])];
if (failures.length > 0) {
  const lines = failures.slice(0, 20).map(f => '- ' + f.type + ' ' + f.id + ': ' + f.error);
  throw new Error(failures.length + ' ' + cfg.label + ' record(s) failed for window ' + cfg.windowFrom + ' to ' + cfg.windowTo
    + '. The window is NOT advanced, so the next run re-reads it (writes are idempotent).\n' + lines.join('\n'));
}

// Full success: advance the watermark. Only persists on production (trigger) runs.
const state = $getWorkflowStaticData('global');
